const n=(r,t=2)=>{if(r==null||r==="")return"--";const e=Number(r);return isNaN(e)?"--":`${Math.abs(e).toFixed(t)}%`},o=r=>r==null||isNaN(r)?"text-gray-400":r>0?"text-green-500":r<0?"text-red-500":"text-gray-500",i=r=>r=="高温影响率"?"text-orange-500":r=="总故障率"?"text-red-500":r=="限电影响率"?"text-yellow-500":"text-blue-500",s=r=>{if(r==null||r==="")return"-";const t=Number(r);return isNaN(t)?"-":(t/1e3).toFixed(3)},u=r=>{if(r==null||r==="")return"--";const t=Number(r);return isNaN(t)?"--":t.toLocaleString()};export{n as a,o as b,u as c,s as f,i as g};
